with ins as (insert into public.artist_press (artist_id,artist_slug,title,publication,url,date_published,type) select a.id,x.s,x.t,x.p,x.u,x.d::date,'feature' from json_to_recordset('[{"s":"su-real","t":"Don''t book Su Real for \"sundowners\", it''s all \"Turn Up\" with Su Real! - In Conversation With Su Real","p":"The Indian Music Diaries","u":"https://theindianmusicdiaries.com/dont-book-su-real-for-sundowners-its-all-turn-up-with-su-real-in-conversation-with-su-real/","d":"2024-02-23"},{"s":"su-real","t":"#HGSessions || Su-Real''s 420 Mix Tape","p":"Homegrown","u":"https://homegrown.co.in/homegrown-explore/hgsessions-002-su-real-s-420-mix-tape","d":null},{"s":"su-real","t":"Exclusive Album Launch: Twerkistan - Su Real","p":"Krunk","u":"https://krunklive.com/exclusive-album-launch-twerkistan-su-real/","d":null}]'::json) as x(s text,t text,p text,u text,d text) join public.artists a on a.slug=x.s on conflict (artist_slug,url) do nothing returning 1) select count(*) from ins;